/****************************************************************************
 * Name: rk3576_spi_exchange
 *
 * Description:
 *   Exchange nwords 8-bit frames over the wire.  The transfer is driven as a
 *   streaming pipeline: while there is free space in the TX FIFO keep feeding
 *   it, and while the RX FIFO holds data keep draining it, until every word
 *   has been pushed and every expected byte read back.  This keeps the, at
 *   most, 64-deep FIFOs busy without per-byte handshaking.
 ****************************************************************************/

static void rk3576_spi_exchange(struct spi_dev_s *dev, const void *txbuffer,
                                void *rxbuffer, size_t nwords)
{
  struct rk3576_spi_priv_s *priv = (struct rk3576_spi_priv_s *)dev;
  const uint8_t *tx = (const uint8_t *)txbuffer;
  uint8_t *rx = (uint8_t *)rxbuffer;
  size_t txoff = 0;
  size_t rxoff = 0;
  size_t before;
  uint32_t stall = 0;
  bool auto_cs = false;

  spiinfo("priv=%p tx=%p rx=%p nwords=%zu\n", priv, tx, rx, nwords);

  /* Without any SS_N enabled the DW SSI controller generates no SCLK, so the
   * RX FIFO never fills and the loop below would spin forever.  If the caller
   * did not select a chip-select (SER == 0), enable CS0 for the duration of
   * this transfer, and clear it again at the end.  Otherwise the caller owns
   * the CS state and we leave it untouched.
   */

  if (spi_getreg(priv, RK3576_SPI_SER_OFFSET) == 0)
    {
      spi_putreg(priv, RK3576_SPI_SER_OFFSET, RK3576_SPI_SER_SER(0));
      auto_cs = true;
    }

  while (txoff < nwords || rxoff < nwords)
    {
      before = txoff + rxoff;

      /* Feed the TX FIFO as long as it has room, but stop once the net
       * in-flight byte count -- pushed-but-not-yet-read-back, i.e.
       * (txoff - rxoff) -- would leave no room left in the RX FIFO.
       *
       * In a full-duplex master the controller shifts one frame out of TX
       * for every frame it samples into RX, so every byte pushed into the
       * TX FIFO is destined for the RX FIFO.  Without this bound a TX feed
       * alone could run ahead of the drain below: a slow CPU feeding a fast
       * SPI would keep topping up the TX FIFO while the RX FIFO, filling in
       * parallel from the shift-out side, silently overflows and drops those
       * excess bytes.  Capping the feed at one RX-FIFO depth of outstanding
       * data -- and letting the drain loop below pull rxoff back up before
       * the feed resumes -- keeps resident RX data within the FIFO forever.
       */

      while (txoff < nwords && rk3576_spi_tx_ready(priv) &&
             (txoff - rxoff) < RK3576_SPI_FIFO_DEPTH)
        {
          uint8_t txb = (tx != NULL) ? tx[txoff] : 0xff;
          spi_putreg(priv, RK3576_SPI_TXDR_OFFSET, txb);
          txoff++;
        }

      /* Drain the RX FIFO as long as it holds data. */

      while (rxoff < nwords && rk3576_spi_rx_ready(priv))
        {
          uint8_t rxb =
              (uint8_t)(spi_getreg(priv, RK3576_SPI_RXDR_OFFSET) & 0xff);
          if (rx != NULL)
            {
              rx[rxoff] = rxb;
            }

          rxoff++;
        }

      if (txoff + rxoff == before)
        {
          if (++stall >= RK3576_SPI_XFER_STALL_LIMIT)
            {
              spierr("ERROR: SPI transfer timed out "
                     "(tx=%zu/%zu rx=%zu/%zu)\n",
                     txoff, nwords, rxoff, nwords);
              goto xfer_timeout;
            }
        }
      else
        {
          stall = 0;
        }
    }

  /* A transmit-only transfer has no RX stream to synchronise on, so make
   * sure the last bytes have actually left the shift register before the
   * upper-half deasserts the chip-select.
   */

  if (rx == NULL)
    {
      rk3576_spi_tx_idle(priv);
    }

  /* Clear the chip-select if we selected it automatically. */

  if (auto_cs)
    {
      spi_putreg(priv, RK3576_SPI_SER_OFFSET, 0);
    }

  return;

xfer_timeout:
  /* Try to recover: dropping SSIENR halts the controller and lets us throw
   * away any half-shifted bytes and stale RX that would otherwise leak into
   * the next exchange.  Re-enable afterwards so the bus is usable again.
   */

  spi_putreg(priv, RK3576_SPI_ENR_OFFSET, 0);

  /* Flush whatever may still be sitting in the RX FIFO so the next transfer
   * begins from a clean, empty RX state.  Bounded so we can never hang here
   * again even if the controller misbehaves.
   */

  stall = 0;
  while (!(spi_getreg(priv, RK3576_SPI_SR_OFFSET) & RK3576_SPI_SR_RFE) &&
         stall++ < RK3576_SPI_FIFO_DEPTH)
    {
      spi_getreg(priv, RK3576_SPI_RXDR_OFFSET);
    }

  spi_putreg(priv, RK3576_SPI_ENR_OFFSET, RK3576_SPI_ENR_EN);

  /* If we raised CS0 ourselves, drop it; the upper-half still thinks the
   * transfer ran to completion and will re-assert CS next time.
   */

  if (auto_cs)
    {
      spi_putreg(priv, RK3576_SPI_SER_OFFSET, 0);
    }
}

