static ssize_t ws2812_write(FAR struct file *filep, FAR const char *buffer,
                            size_t buflen)
{
  FAR struct inode *inode = filep->f_inode;
  FAR struct ws2812_dev_s *priv = inode->i_private;
  FAR uint8_t *tx;
  size_t npixels;
  size_t i;

  if (buffer == NULL || buflen == 0 ||
      (buflen % WS2812_PIXEL_SIZE) != 0)
    {
      lederr("ERROR: ...\n");
      return -EINVAL;
    }

  npixels = buflen / WS2812_PIXEL_SIZE;
  if (npixels > CONFIG_WS2812_CHARDEV_MAX_PIXELS)
    {
      return -EFBIG;
    }

  nxmutex_lock(&priv->lock);

  memset(priv->txbuf, 0, WS2812_RST_CYCLES);
  tx = priv->txbuf + WS2812_RST_CYCLES;

  for (i = 0; i < npixels; i++)
    {
      uint32_t rgb;
      memcpy(&rgb, buffer + i * WS2812_PIXEL_SIZE, sizeof(rgb));
      ws2812_pack(tx, rgb & 0xffffff);
      tx += WS2812_BYTES_PER_LED;
    }

  *tx = 0;

  ws2812_lock(priv);

  SPI_SETMODE(priv->spi, SPIDEV_MODE3);
  SPI_SETBITS(priv->spi, 8);
  SPI_SETFREQUENCY(priv->spi, CONFIG_WS2812_CHARDEV_FREQUENCY);
  SPI_SNDBLOCK(priv->spi, priv->txbuf,
               WS2812_RST_CYCLES + npixels * WS2812_BYTES_PER_LED + 1);

  ws2812_unlock(priv);

  nxmutex_unlock(&priv->lock);

  return buflen;
}
```

